"                <div class=\"form-main-container\">\n"
"                    <h3 class=\"heading\">Sign In</h3>\n"
"                    <form class=\"form\" action=\"/scorpioStatus\" method=\"get\">\n"
"                        <input type=\"text\" class=\"username\" placeholder=\"Username\" class=\"input\" />\n"
"                        <input type=\"password\" class=\"password\" placeholder=\"Password\" class=\"input\" />\n"
"                        <button type=\"submit\">Sign in</button>\n"
"                    </form>\n"
"                </div>\n"
"            </div>\n"
"        </section>\n"
"    </div>\n"
"</body>\n"
"<script>\n"
"    document.addEventListener(\"DOMContentLoaded\", async function () {\n"
"  console.log(\"Starting initialization...\");\n"
"  \n"
"  try {\n"
"    // Load critical resources first\n"
"    await fetchBgGreen(retry=false);\n"
"    await fetchEmcusIconData(retry=false);\n"
"    \n"
"    // Then load non-critical assets\n"
"    await Promise.all([\n"
"      fetchBgBlue(),\n"
"      fetchEmcusLogo()\n"
"    ]);\n"
"    \n"
"  } catch (error) {\n"
"    console.error(\"Initialization failed:\", error);\n"
"    showError(\"Failed to initialize: \" + error.message);\n"
"  }\n"
"        const form = document.querySelector(\"form\");\n"
"        form.addEventListener(\"submit\", function (event) {\n"
"            event.preventDefault();\n"
"\n"
"            const username = document.getElementsByClassName(\"username\")[0].value;\n"
"            const password = document.getElementsByClassName(\"password\")[0].value;\n"
"\n"
"            if (username === \"EmcusAdmin\" && password === \"EmcusAdmin\") {\n"
"                try {\n"
"                   fetch(`http://%s/scorpioStatus`)\n"
"                   .then(response => response.text())\n"
"                   .then(html => {\n"
"                         document.open();\n"
"                         document.write(html);\n"
"                         document.close();\n"
"                })\n"
"                .catch(error => {\n"
"                     console.error('Error:', error);\n"
"                     alert(\"Error fetching data. Please try again.\");\n"
"                });\n"
"                } catch (error) {\n"

"                    console.log(\"Error: \", error);\n"

"                }\n"
 
"            } else {\n"
"                alert(\"Invalid Credentials\");\n"
"            }\n"
"        });\n"
"    });\n"
"\n"
"async function fetchEmcusIconData(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/emcus-icon.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            },\n"
"        });\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".emcus-icon\").src = imgURL;\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchEmcusIconData(retry=true);\n"
"        }\n"
"        console.error('Error:', error);\n"
"        alert(\"Error fetching data. Please try again.\");\n"
"    }\n"
"}\n"
"\n"
"async function fetchBgBlue(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/bg-blue.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            },\n"
"        });\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".blue\").src = imgURL;\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchBgBlue(retry=true);\n"
"        }\n"
"        console.error('Error:', error);\n"
"    }\n"
"}\n"

"\n"
"async function fetchBgGreen(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/bg-green.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            },\n"
"        });\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".green\").src = imgURL;\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchBgGreen(retry=true);\n"
"        }\n"
"        console.error('Error:', error);\n"
"    }\n"
"}\n"
"\n"
"async function fetchEmcusLogo() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/emcus-logo.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            },\n"
"        });\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".emcus-logo\").src = imgURL;\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchEmcusLogo(retry=true);\n"
"        }\n"
"        console.error('Error:', error);\n"
"    }\n"
"}\n"
"</script>\n"
"\n"
"</html>";

