"<script>\n"
"    let enabled = true;\n"
"    function toggleState() {\n"
"        enabled = !enabled;\n"
"        document.getElementById(\"enableOption\").classList.toggle(\"active\", enabled);\n"
"        document.getElementById(\"disableOption\").classList.toggle(\"active\", !enabled);\n"
"    }\n"
"\n"
"async function fetchBgBlue() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/bg-blue.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".blue\").src = imgURL;\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading blue background:', error);\n"
"    }\n"
"}"

"\n"
"async function fetchBgGreen(retry=false) {\n"
"    try {\n"
"        const response = await fetch(\"http://%s/bg-green.png\", {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".green\").src = imgURL;\n"
"        \n"
"        // Fetch data after successful image load\n"
"        await fetchData();\n"
"        retry=false;\n"
"        \n"
"    } catch (error) {\n"
"       if(retry){\n"
"        await fetchBgGreen(retry=true);\n"
"       }\n"
"        console.error('Error loading green background:', error);\n"
"        \n"
"    }\n"
"}"
"\n"
"async function fetchEmcusLogo() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/emcus-logo.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        \n"
"        // Load next resource after successful logo load\n"
"        await fetchBgBlue();\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading logo:', error);\n"
"    }\n"
"}"
"function updateStatusPage(data) {\n"
"        const lines = data.trim().split('\\n').filter(line => line.trim() !== '');\n"

"        const lastLine = lines[lines.length - 1];\n"

"        console.log('Parsed Line:', lastLine);\n"

"\n"

"        const parts = lastLine.split(/\\s+/);\n"

"        console.log('Parts:', parts);\n"

"        const scorpioVersion = parts[0] || 'N/A';\n"

"        const geminiVersion = parts[1] || 'N/A';\n"

"        let ipStatus = parts[2] || 'N/A';\n"

"        let gsmStatus = parts[3] || 'N/A';\n"

"        const gsmNumber = parts[4] || 'N/A';\n"
"        const staticIP = parts[5] || 'N/A';\n"
"        if(ipStatus == \"0\"){\n"
"           ipStatus=\"Disabled\"\n"
"        }else{\n"
"           ipStatus=\"Enabled\"\n"
"        }\n"
"        if(gsmStatus == \"0\"){\n"
"           gsmStatus=\"Disabled\"\n"
"        }else{\n"
"           gsmStatus=\"Enabled\"\n"
"        }\n"
"\n"

"        const rows = document.querySelectorAll(\".data-row\")\n"

"\n"

"        rows.forEach(row => {\n"

"            const labels = row.querySelectorAll(\"h5\");\n"

"            if (labels.length !== 2) return;\n"

"\n"

"            const label = labels[0].textContent.trim();\n"

"            const valueElem = labels[1];\n"

"\n"

"            if (label.includes(\"Scorpio Version\")) {\n"

"                valueElem.textContent = scorpioVersion;\n"

"            } else if (label.includes(\"Gemini Version\")) {\n"

"                valueElem.textContent = geminiVersion;\n"

"            } else if (label.includes(\"IP Status\")) {\n"

"                valueElem.textContent = ipStatus;\n"

"            } else if (label.includes(\"GSM Status\")) {\n"

"                valueElem.textContent = gsmStatus;\n"

"            } else if (label.includes(\"GSM Mobile Number\")) {\n"

"                valueElem.textContent = gsmNumber;\n"

"            } else if (label.includes(\"Static IP\")) {\n"

"                valueElem.textContent = staticIP;\n"

"            }\n"

"        });\n"

"\n"

"        const ipStatusElement = document.getElementById(\"ip-status\")\n"

"        const gsmStatusElement = document.getElementById(\"gsm-status\")\n"

"\n"

"        if(ipStatus){\n"

"            ipStatusElement.textContent = \"Enabled\";\n"

"        }else{\n"

"            ipStatusElement.textContent = \"Disabled\"\n"

"        }\n"

"\n"

"        if(gsmStatus){\n"

"            gsmStatusElement.textContent = \"Enabled\";\n"

"        }else{\n"

"            gsmStatusElement.textContent = \"Disabled\"\n"

"        }\n"

"    }\n"
"async function fetchData(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/status_config`, {\n"
"            method: \"GET\"\n"
"            // headers: {\n"
"            //     \"Content-Type\": \"application/json\",\n"
"            //     \"Accept\": \"application/json\"\n"
"            // }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const contentType = response.headers.get('content-type');\n"
"        let data;\n"
"\n"
"        if (contentType && contentType.includes('application/json')) {\n"
"            data = await response.json();\n"
"            console.log(\"JSON Response:\", data);\n"
"        } else {\n"
"            data = await response.text();\n"
"            console.log(\"Text Response:\", data);\n"
"        }\n"
"\n"
"        updateStatusPage(data);\n"
"        return true;\n"
"\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchData(retry=true);\n"
"        }\n"
"        console.error(\"Fetch error:\", error);\n"
"        \n"
"        return false;\n"
"    }\n"
"}"
"document.addEventListener(\"DOMContentLoaded\", async () => {\n"
"  console.log(\"Starting initialization...\");\n"
"  \n"
"  try {\n"
"    // Load critical resources first\n"
"    await fetchBgGreen(); \n"
"    await fetchData();\n"
"    \n"
"    // Then load non-critical assets\n"
"    await Promise.all([\n"
"      fetchBgBlue(),\n"
"      fetchEmcusLogo()\n"
"    ]);\n"
"    \n"
"  } catch (error) {\n"
"    console.error(\"Initialization failed:\", error);\n"
"  }\n"
"});\n"
"</script>\n"
"\n"
"\n"
"</html>";

