"\n"
"<body>\n"
"    <div class=\"background\">\n"
"        <div class=\"sub-background\">\n"
"            <img src=\"/emcus-logo.png\" class=\"emcus-logo\" width=\"180px\" />\n"
"            <div class=\"navbar\">\n"
"                <div class=\"nav-item\">\n"
"                    <a href=\"/scorpioStatus\" class=\"nav-item\">\n"
"                        <h5>Scorpio Status</h5>\n"
"                    </a>\n"
"                </div>\n"
"                <div class=\"nav-item active\">\n"
"                    <a href=\"/ipConfigPage\" class=\"nav-item\">\n"
"                        <h5>IP Configuration</h5>\n"
"                    </a>\n"
"                </div>\n"
"                <div class=\"nav-item\">\n"
"                    <a href=\"/gsmConfigPage\" class=\"nav-item\">\n"
"                        <h5>GSM Configuration</h5>\n"
"                    </a>\n"
"                </div>\n"
"                <div class=\"nav-item\">\n"
"                    <a href=\"/certConfigPage\" class=\"nav-item\">\n"
"                        <h5>Certificate & URL</h5>\n"
"                    </a>\n"
"                </div>\n"
"            </div>\n"
"            <img src=\"/bg-blue.png\" height=\"100%%\" width=\"100%%\" class=\"blue\" />\n"
"        </div>\n"
"        <img src=\"/bg-green.png\" height=\"40%%\" width=\"20%%\" class=\"green\" />\n"
"        <section class=\"content-pane\">\n"
"            <div class=\"content\">\n"
"                <div class=\"heading\">\n"
"                    <h2>IP Selection</h2>\n"
"                    <h5>Information Panel</h5>\n"
"                </div>\n"
"                <div class=\"ip-config-form-container\">\n"
"                    <div class=\"enable-disable\">\n"
"                        <h3>IP Selection</h3>\n"
"                        <div class=\"toggle-container\" onclick=\"toggleState()\">\n"
"                            <div class=\"toggle-option active\" id=\"enableOption\">Enable</div>\n"
"                            <div class=\"toggle-option\" id=\"disableOption\">Disable</div>\n"
"                        </div>\n"
"                    </div>\n"
"                    <form id=\"ip-form\">\n"
"                        <h3 class=\"enable-disable-title\">Static IPv4 Configuration</h3>\n"
"                        <div class=\"form-input\">\n"
"                            <div class=\"row-input-div\">\n"
"                                <div class=\"input-div\">\n"
"                                    <label>Static IP</label>\n"
"                                    <input type=\"text\" id=\"static-ip\" />\n"
"                                </div>\n"
"                                <div class=\"input-div\">\n"
"                                    <label>Net Mask</label>\n"
"                                    <input type=\"text\" id=\"net-mask\" />\n"
"                                </div>\n"
"                            </div>\n"
"                            <div class=\"input-div gateway\">\n"
"                                <label>Gateway Address</label>\n"
"                                <input type=\"text\" id=\"gateway-address\" />\n"
"                            </div>\n"
"                        </div>\n"
"                        <button type=\"submit\">Submit</button>\n"
"                    </form>\n"
"                </div>\n"
"            </div>\n"
"        </section>\n"
"    </div>\n"
"</body>\n"
"<script>\n"
"    let enabled = true;\n"
"    function toggleState() {\n"
"        enabled = !enabled;\n"
"        document.getElementById(\"enableOption\").classList.toggle(\"active\", enabled);\n"
"        document.getElementById(\"disableOption\").classList.toggle(\"active\", !enabled);\n"
"    }\n"
"\n"
"async function fetchBgBlue() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/bg-blue.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".blue\").src = imgURL;\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading blue background:', error);\n"
"    }\n"
"}"

"\n"
"async function fetchBgGreen(retry=false) {\n"
"    try {\n"
"        const response = await fetch(\"http://%s/bg-green.png\", {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".green\").src = imgURL;\n"
"        \n"
"        // Fetch data after successful image load\n"
"        await fetchData();\n"
"        retry = false;\n"
"        \n"
"    } catch (error) {\n"
"       if(retry){\n"
"        await fetchBgGreen(retry=true);\n"
"       }\n"
"        console.error('Error loading green background:', error);\n"
"        \n"
"    }\n"
"}"
"\n"
"async function fetchEmcusLogo() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/emcus-logo.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        \n"
"        // Load next resource after successful logo load\n"
"        await fetchBgBlue();\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading logo:', error);\n"
"    }\n"
"}"
"document.getElementById(\"ip-form\").addEventListener(\"submit\", async function (event) {\n"
"        event.preventDefault();\n"
"\n"
"        const data = {\n"
"            staticIP: document.getElementById(\"static-ip\").value,\n"
"            netMask: document.getElementById(\"net-mask\").value,\n"
"            gatewayAddress: document.getElementById(\"gateway-address\").value,\n"
"            ipSelection: enabled?\"ENABLED\":\"DISABLED\",\n"
"        };\n"
"        console.log(data)\n"
"\n"
"        // return data;\n"
"\n"
"        try {\n"
"            fetch(\"http://%s/ip_config\", {\n"
"                method: \"POST\",\n"
"                mode: \"cors\",\n"
"                headers: {\n"
"                    \"Content-Type\": \"application/json\",\n"
"                    \"Accept\": \"application/json\"\n"
"                },\n"
"                body: JSON.stringify(data)\n"
"            })\n"
"                .then(response => {\n"
"                    if (!response.ok) {\n"
"                        console.log(`HTTP error! Status: ${response.status}`);\n"
"                    }\n"
"                    response.text()\n"
"                })\n"
"                .then(data => {\n"
"                    console.log('Response:', data)\n"
"                    alert(\"Data successfully submitted!\");\n"
"                })\n"
"                .catch(error => {\n"
"                    console.error('Error:', error);\n"
"                });\n"
"\n"
"        } catch (error) {\n"
"            console.error(\"Error submitting data:\", error);\n"
"        }\n"
"\n"
"    });\n"
"    function updateIpPage(data) {\n"
"        const lines = data.trim().split('\\n').filter(line => line.trim() !== '');\n"
"        const lastLine = lines[lines.length - 1];\n"
"        console.log('Parsed Line:', lastLine);\n"
"\n"
"        const parts = lastLine.split(/\\s+/);\n"
"        console.log('Parts:', parts);\n"
"        const staticIP = parts[0] || '';\n"
"        const netMask = parts[1] || '';\n"
"        const gatewayAddress = parts[2] || '';\n"
"        const ipEnable = parts[3] || '';\n"
"        if(ipEnable == \"0\"){\n"
"           enabled = false;\n"
"           document.getElementById(\"enableOption\").classList.toggle(\"active\", enabled);\n"
"           document.getElementById(\"disableOption\").classList.toggle(\"active\", !enabled);\n"
"        }else{\n"
"           enabled = true;\n"
"           document.getElementById(\"enableOption\").classList.toggle(\"active\", enabled);\n"
"           document.getElementById(\"disableOption\").classList.toggle(\"active\", !enabled);\n"
"        }\n"
"\n"
"        const tableRows = document.querySelectorAll(\".form-input .input-div\");\n"
"        tableRows.forEach(row => {\n"
"            const label = row.querySelector(\"label\");\n"
"            const input = row.querySelector(\"input\");\n"
"            if (!input) return;\n"
"\n"
"            if (label.textContent.includes(\"Static IP\")) {\n"
"                input.value= staticIP;\n"
"            } else if (label.textContent.includes(\"Net Mask\")) {\n"
"                input.value = netMask;\n"
"            } else if (label.textContent.includes(\"Gateway Address\")) {\n"
"                input.value = gatewayAddress;\n"
"            }\n"
"        });\n"
"    }\n"
 "async function fetchIpData(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/ipdata`, {\n"
"            method: \"GET\"\n"
"            // headers: {\n"
"            //     \"Content-Type\": \"application/json\",\n"
"            //     \"Accept\": \"application/json\"\n"
"            // }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const contentType = response.headers.get('content-type');\n"
"        let data;\n"
"\n"
"        if (contentType && contentType.includes('application/json')) {\n"
"            data = await response.json();\n"
"            console.log(\"JSON Response:\", data);\n"
"        } else {\n"
"            data = await response.text();\n"
"            console.log(\"Text Response:\", data);\n"
"        }\n"
"\n"
"        updateIpPage(data);\n"
"        return true;\n"
"\n"
"    } catch (error) {\n"
"       retry = !retry;\n"
"       if(retry){\n"
"        await fetchIpData(retry=true);\n"
"       }\n"
"        console.error(\"Fetch error:\", error);\n"
"        \n"
"        return false;\n"
"    }\n"
"}"
"document.addEventListener(\"DOMContentLoaded\", async () => {\n"
"  console.log(\"Starting initialization...\");\n"
"  \n"
"  try {\n"
"    // Load critical resources first\n"
"    await fetchBgGreen(); \n"
"    await fetchIpData();\n"
"    \n"
"    // Then load non-critical assets\n"
"    await Promise.all([\n"
"      fetchBgBlue(),\n"
"      fetchEmcusLogo()\n"
"    ]);\n"
"    \n"
"  } catch (error) {\n"
"    console.error(\"Initialization failed:\", error);\n"
"  }\n"
"});\n"
"</script>\n"
"\n"
"\n"
"</html>";


