"</body>"
"<script>\n"
"    let enabled = true;\n"
"    function toggleState() {\n"
"        enabled = !enabled;\n"
"        document.getElementById(\"enableOption\").classList.toggle(\"active\", enabled);\n"
"        document.getElementById(\"disableOption\").classList.toggle(\"active\", !enabled);\n"
"    }\n"
"\n"
"async function fetchBgBlue() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/bg-blue.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".blue\").src = imgURL;\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading blue background:', error);\n"
"    }\n"
"}"

"\n"
"async function fetchBgGreen(retry=false) {\n"
"    try {\n"
"        const response = await fetch(\"http://%s/bg-green.png\", {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        document.querySelector(\".green\").src = imgURL;\n"
"        \n"
"        // Fetch data after successful image load\n"
"        await fetchData();\n"
"        \n"
"    } catch (error) {\n"
"       retry = !retry;\n"
"       if(retry){\n"
"        await fetchBgGreen(retry=true);\n"
"       }\n"
"        console.error('Error loading green background:', error);\n"
"        \n"
"    }\n"
"}"
"\n"
"async function fetchEmcusLogo() {\n"
"    try {\n"
"        const response = await fetch(`http://%s/emcus-logo.png`, {\n"
"            method: \"GET\",\n"
"            headers: {\n"
"                \"Content-Type\": \"image/png\",\n"
"                \"Accept\": \"image/png\"\n"
"            }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const blob = await response.blob();\n"
"        const imgURL = URL.createObjectURL(blob);\n"
"        \n"
"        // Load next resource after successful logo load\n"
"        await fetchBgBlue();\n"
"\n"
"    } catch (error) {\n"
"        console.error('Error loading logo:', error);\n"
"    }\n"
"}"
"document.getElementById(\"certificate-form\").addEventListener(\"submit\", async function (event) {\n"
"        event.preventDefault();\n"
"\n"
"        function toFormattedCertificateString(pem) {\n"
"            const lines = pem.trim().split('\\n');\n"
"            const joined = lines.join('\\n');\n"
"            return `\"${joined}\\n\";`;\n"
"        }\n"
"        function toSingleLineCertificate(pem) {\n"
"            // Remove all line breaks and trim any extra spaces\n"
"            return pem.replace(/\\r?\\n/g, '').trim();\n"
"        }\n"
"\n"
"        const cloudURL = document.getElementById(\"cloud-url\").value;\n"
"        const fileData = document.getElementById(\"certificate\");\n"
"\n"
"        if (!cloudURL) {\n"
"            alert(\"Enter cloud url\");\n"
"            return;\n"
"        }\n"
"\n"
"        if (!fileData.files.length) {\n"
"            alert(\"Please select a certificate file.\");\n"
"            return;\n"
"        }\n"
"\n"
"        const file = fileData.files[0];\n"
"        const reader = new FileReader();\n"
"        reader.onload = function (e) {\n"
"            const fileContent = e.target.result;\n"
"            const certificateFormatted = toSingleLineCertificate(fileContent);\n"
"\n"
"            const maxSize = 3 * 1024; // 3 KB in bytes\n"
"            if (file.size > maxSize) {\n"
"                alert(\"File size exceeds 3 KB. Please upload a smaller certificate file.\");\n"
"                return;\n"
"            }\n"
"\n"
"            const validExtensions = ['pem', 'crt', 'txt'];\n"
"            const fileExtension = file.name.split('.').pop().toLowerCase();\n"
"\n"
"            if (!validExtensions.includes(fileExtension)) {\n"
"                alert(\"Invalid file type. Please upload a .pem, .crt, or .txt file.\");\n"
"                return;\n"
"            }\n"
"\n"
"            const data = {\n"
"                cloudURL: cloudURL,\n"
"                certificate: certificateFormatted,\n"
"            };\n"
"\n"
"            console.log(data);\n"
"\n"
"            fetch(\"http://%s/certificate_url_config\", {\n"
"                method: \"POST\",\n"
"                mode: \"cors\",\n"
"                headers: {\n"
"                    \"Content-Type\": \"application/json\",\n"
"                    \"Accept\": \"application/json\"\n"
"                },\n"
"                body: JSON.stringify(data)\n"
"            })\n"
"                .then(response => {\n"
"                    if (!response.ok) {\n"
"                        console.log(`HTTP error! Status: ${response.status}`);\n"
"                    }\n"
"                    return response.text();\n"
"                })\n"
"                .then(responseData => {\n"
"                    console.log(\"Response:\", responseData);\n"
"                    alert(\"Data successfully submitted!\");\n"
"                })\n"
"                .catch(error => {\n"
"                    console.error(\"Error:\", error);\n"
"                });\n"
"        };\n"
"\n"
"        reader.onerror = function () {\n"
"            alert(\"Error reading certificate file.\");\n"
"        };\n"
"\n"
"        reader.readAsText(file);\n"
"    });\n"
    "function updateCertPage(data) {\n"
"        const lines = data.trim().split('\\n').filter(line => line.trim() !== '');\n"
"        const lastLine = lines[lines.length - 1];\n"
"        console.log('Parsed Line:', lastLine);\n"
"\n"
"        const parts = lastLine.split(/\\s+/);\n"
"        console.log('Parts:', parts);\n"
"        const cloudURL = parts[0] || '';\n"
"\n"
"        const tableRows = document.querySelectorAll(\".form-input .input-div\");\n"
"        tableRows.forEach(row => {\n"
"            const label = row.querySelector(\"label\");\n"
"            const input = row.querySelector(\"input\");\n"
"            if (!input) return;\n"
"\n"
"            if (label.textContent.includes(\"Cloud URL\")) {\n"
"                    input.value= cloudURL;\n"
"            }\n"
"        });\n"
"    }\n"
 "async function fetchCertData(retry=false) {\n"
"    try {\n"
"        const response = await fetch(`http://%s/certificatedata`, {\n"
"            method: \"GET\"\n"
"            // headers: {\n"
"            //     \"Content-Type\": \"application/json\",\n"
"            //     \"Accept\": \"application/json\"\n"
"            // }\n"
"        });\n"
"\n"
"        if (!response.ok) {\n"
"            throw new Error(`HTTP error! Status: ${response.status}`);\n"
"        }\n"
"\n"
"        const contentType = response.headers.get('content-type');\n"
"        let data;\n"
"\n"
"        if (contentType && contentType.includes('application/json')) {\n"
"            data = await response.json();\n"
"            console.log(\"JSON Response:\", data);\n"
"        } else {\n"
"            data = await response.text();\n"
"            console.log(\"Text Response:\", data);\n"
"        }\n"
"\n"
"        updateCertPage(data);\n"
"        return true;\n"
"\n"
"    } catch (error) {\n"
"        retry = !retry;\n"
"        if(retry){\n"
"            await fetchCertData(retry=true);\n"
"        }\n"
"        console.error(\"Fetch error:\", error);\n"
"        \n"
"        return false;\n"
"    }\n"
"}"
"document.addEventListener(\"DOMContentLoaded\", async () => {\n"
"  console.log(\"Starting initialization...\");\n"
"  \n"
"  try {\n"
"    // Load critical resources first\n"
"    await fetchBgGreen(); \n"
"    await fetchCertData();\n"
"    \n"
"    // Then load non-critical assets\n"
"    await Promise.all([\n"
"      fetchBgBlue(),\n"
"      fetchEmcusLogo()\n"
"    ]);\n"
"    \n"
"  } catch (error) {\n"
"    console.error(\"Initialization failed:\", error);\n"
"  }\n"
"});\n"
"</script>\n"
"\n"
"\n"
"</html>";

